<script lang="ts">
 import type {Project} from "./model";import {translator} from "./i18n";import {paymentReport,paymentReportCSV,paymentReportHTML,paymentReportXLSX} from "./payment-report";import {displayDate} from "./date-format";import {monthNext} from "./engine";import {exportText,exportBinary,exportPDF,native} from "./storage";import {ReceiptText,Printer,Download} from "@lucide/svelte";
 export let project:Project;
 let from=project.settings.period+"-01",to=new Date(Date.parse(monthNext(project.settings.period)+"-01T00:00:00Z")-86400000).toISOString().slice(0,10),accountId="",attentionOnly=false,generated="",error="",ready=false,preview:HTMLIFrameElement;
 $: t=translator(project.settings.language);
 $: report=(()=>{try{return paymentReport(project,from,to,accountId,attentionOnly);}catch{return null;}})();
 function generate(){try{generated=paymentReportHTML(project,from,to,accountId,attentionOnly);ready=false;error="";}catch(e){error=String(e);}}
 async function download(){try{await exportText(`OpenHaU-payments-${from}-${to}.csv`,paymentReportCSV(project,from,to,accountId,attentionOnly),"csv");}catch(e){error=String(e);}}
</script>
<div class="payment-report">
 <div class="two-fields"><label>{t("С даты","De la data")}<input type="date" bind:value={from}/></label><label>{t("По дату","Până la data")}<input type="date" bind:value={to}/></label><label>{t("Лицевой счёт","Cont personal")}<select bind:value={accountId}><option value="">{t("Все счета","Toate conturile")}</option>{#each project.accounts as a}<option value={a.id}>{a.number} · {a.payer_name}</option>{/each}</select></label></div>
 <label class="check-row"><input type="checkbox" bind:checked={attentionOnly}/>{t("Требует распределения","Necesită repartizare")}</label><div class="toolbar"><button class="button" onclick={generate}><ReceiptText size={16}/>{t("Сформировать","Generează")}</button><button class="button secondary" disabled={!ready} onclick={()=>{preview.contentWindow?.focus();preview.contentWindow?.print();}}><Printer size={16}/>{t("Печать","Imprimare")}</button><button class="button secondary" disabled={!native||!report} onclick={async()=>{try{await exportPDF(`OpenHaU-payments-${from}-${to}.pdf`,paymentReportHTML(project,from,to,accountId,attentionOnly),true);}catch(e){error=String(e);}}}><Download size={16}/>{t("Сохранить PDF","Salvează PDF")}</button><button class="button secondary" onclick={async()=>{try{await exportBinary(`OpenHaU-payments-${from}-${to}.xlsx`,paymentReportXLSX(project,from,to,accountId,attentionOnly),"xlsx");}catch(e){error=String(e);}}}><Download size={16}/>Excel XLSX</button><button class="button secondary" onclick={download}><Download size={16}/>CSV</button></div>
 {#if error}<p role="alert">{error}</p>{/if}
 {#if generated}<iframe title={t("Предпросмотр отчёта по оплатам","Previzualizarea raportului de plăți")} bind:this={preview} srcdoc={generated} sandbox="allow-same-origin allow-modals" onload={()=>ready=true}></iframe>{:else if report}<p>{t("Платежей","Plăți")}: {report.count} · {t("Итого","Total")}: {report.total} MDL</p><div class="table-wrap"><table><thead><tr><th>{t("Дата","Data")}</th><th>{t("Счёт","Cont")}</th><th>{t("Плательщик","Plătitor")}</th><th>MDL</th><th>{t("Способ / документ","Metodă / document")}</th><th>{t("Проверка","Verificare")}</th></tr></thead><tbody>{#each report.rows as pay}<tr class:attention-row={pay.unallocated!=="0.00"}><td>{displayDate(pay.payment_date,project)}</td><td>{pay.number}</td><td>{pay.payer}</td><td>{pay.amount}</td><td>{pay.method} {pay.document}</td><td>{pay.unallocated!=="0.00"?t("Не распределено: ","Nerepartizat: ")+pay.unallocated+" MDL":"—"}</td></tr>{/each}</tbody></table></div>{:else}<p role="alert">{t("Проверьте диапазон дат","Verificați intervalul de date")}</p>{/if}
</div>
<style>.payment-report{display:flex;flex-direction:column;gap:16px;padding:16px}.toolbar{display:flex;gap:8px;flex-wrap:wrap}label{display:flex;flex-direction:column;gap:6px}iframe{width:100%;min-height:500px;border:1px solid var(--border);background:white}</style>

